import type { Lesson } from "../lib/types";

const schedule = [
  { label: "温故与诊断", minutes: 8, detail: "先回忆与判断，暴露直觉中的空白" },
  { label: "核心概念", minutes: 25, detail: "理解定义、因果链与适用边界" },
  { label: "案例与图表", minutes: 18, detail: "用明确标注的模拟商业情境检验概念" },
  { label: "练习与解析", minutes: 18, detail: "先作答，再显示答案和逐步解析" },
  { label: "总结与反思", minutes: 6, detail: "提炼结论，写反思并安排间隔复习" },
] as Lesson["schedule"];

const reflections: Lesson["reflectionPrompts"] = [
  "我今天能解释什么？",
  "我还不懂什么？",
  "今天如何应用？",
];

function makeLesson(input: Omit<Lesson, "schedule" | "reflectionPrompts" | "duration" | "difficulty"> & Partial<Pick<Lesson, "duration" | "difficulty">>): Lesson {
  return {
    ...input,
    duration: input.duration ?? 75,
    difficulty: input.difficulty ?? "零基础",
    schedule,
    reflectionPrompts: reflections,
  };
}

